def clean_html(text):
    if not text:
        return ""
    text = re.sub(r'<[^>]+>', '', text)
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def sort_key(h):
    hn = h["hadithnumber"]
    parts = hn.split(".")
    return (int(parts[0]), float(parts[1]) if len(parts) > 1 else 0)

def main():
    print("Loading English reference data...")
    with open(EN_PATH, "r", encoding="utf-8") as f:
        en_data = json.load(f)
    en_map = {str(item["hadithnumber"]): item for item in en_data if "hadithnumber" in item}
    print(f"Loaded {len(en_map)} English hadith records.")

    print("Loading Urdu source data...")
    with open(UR_SRC_PATH, "r", encoding="utf-8") as f:
        ur_src = json.load(f)
    ur_hadiths = ur_src.get("hadiths", [])
    print(f"Loaded {len(ur_hadiths)} Urdu hadiths from source.")

    converted_list = []
    injected_count = 0

    for idx, h in enumerate(ur_hadiths):
        hn = str(h["hadithnumber"])
        
        # Check if text is empty and if we have a translation in our dictionary
        text = h.get("text", "").strip()
        if not text and hn in EXTRA_TRANSLATIONS:
            text = EXTRA_TRANSLATIONS[hn]
            injected_count += 1
        
        # Clean text
        text = clean_html(text)

        # Lookup English metadata
        if hn in en_map:
            en_ref = en_map[hn]
            narrator = en_ref.get("narrator", "")
            status = en_ref.get("status", "")
            reference = en_ref.get("reference", "")
            in_book_reference = en_ref.get("in_book_reference", "")
        else:
            narrator = ""
            status = ""
            reference = f"Sunan Abi Dawud {hn}"
            ref_dict = h.get("reference", {})
            if isinstance(ref_dict, dict) and "book" in ref_dict and "hadith" in ref_dict:
                in_book_reference = f"Book {ref_dict['book']}, Hadith {ref_dict['hadith']}"
            else:
                in_book_reference = f"Hadith {hn}"

        # Clean metadata strings
        narrator = clean_html(narrator)
        status = clean_html(status)
        reference = clean_html(reference)
        in_book_reference = clean_html(in_book_reference)

        converted_list.append({
            "hadithnumber": hn,
            "narrator": narrator,
            "status": status,
            "reference": reference,
            "in_book_reference": in_book_reference,
            "text": text
        })

    # Sort the converted hadiths numerically
    converted_list = sorted(converted_list, key=sort_key)

    # Write output to file
    os.makedirs(os.path.dirname(UR_OUT_PATH), exist_ok=True)
    with open(UR_OUT_PATH, "w", encoding="utf-8") as f:
        json.dump(converted_list, f, ensure_ascii=False, indent=2)

    print(f"\nSuccessfully wrote {len(converted_list)} hadiths to {UR_OUT_PATH}")
    print(f"Injected {injected_count} missing translations.")
    
    # Simple sanity checks
    empty_text_count = sum(1 for h in converted_list if not h["text"].strip())
    print(f"Hadiths with empty text: {empty_text_count}")

if __name__ == "__main__":
    main()
